export const BentoStatCard = ({ title = "Aylık Tekrarlayan Ciro (MRR)", value = "$8,420", growth = "+24.8%" }) => (
  <div className="rounded-3xl bg-slate-950/80 backdrop-blur-xl border border-slate-800/60 p-6 shadow-2xl relative overflow-hidden group hover:border-emerald-500/40 transition-all duration-300">
