export const ClientROICalculator = ({ leadValue = 150 }) => {
  const [extraLeads, setExtraLeads] = React.useState(12);
  const monthlyGain = extraLeads * leadValue;
  return (
    <div className="rounded-3xl bg-slate-900/60 border border-slate-800 p-8 space-y-6 max-w-lg mx-auto">
      <div className="flex justify-between items-center">
        <span className="text-slate-300 font-medium">Aylık Ek Hasta/Müşteri:</span>
        <span className="text-2xl font-black text-emerald-400">+{extraLeads}</span>
      </div>
      <input
        type="range" min="2" max="50" value={extraLeads}
        onChange={(e) => setExtraLeads(Number(e.target.value))}
        className="w-full accent-emerald-500 cursor-pointer"
      />
      <div className="p-4 rounded-2xl bg-emerald-950/30 border border-emerald-500/20 text-center">
        <div className="text-xs text-emerald-400 font-semibold uppercase tracking-wider">Tahmini Ek Yıllık Ciro</div>
        <div className="text-3xl font-extrabold text-white mt-1">${(monthlyGain * 12).toLocaleString()}</div>
      </div>
    </div>
  );
};
